import { gs } from '@servicenow/glide'

export function formatRealignmentLine(current, previous) {
    // Auto-populate from/to cost center fields based on line type
    if (current.getValue('line_type') == 'source') {
        // Source line: cost center is the FROM center
        current.setValue('from_cost_center', current.getValue('cost_center'));
        current.setValue('to_cost_center', '');

        // Set debit amount (positive)
        const amount = parseFloat(current.getValue('amount') || 0);
        current.setValue('debit_amount', amount);
        current.setValue('credit_amount', 0);

        // Format as positive debit: $1,200
        current.setValue('formatted_amount', '$' + amount.toLocaleString('en-US', {
            minimumFractionDigits: 2,
            maximumFractionDigits: 2
        }));

    } else if (current.getValue('line_type') == 'destination') {
        // Destination line: cost center is the TO center
        current.setValue('to_cost_center', current.getValue('cost_center'));
        current.setValue('from_cost_center', '');

        // Set credit amount (positive)
        const amount = parseFloat(current.getValue('amount') || 0);
        current.setValue('credit_amount', amount);
        current.setValue('debit_amount', 0);

        // Format as credit with parentheses: ($1,200.00)
        current.setValue('formatted_amount', '($' + amount.toLocaleString('en-US', {
            minimumFractionDigits: 2,
            maximumFractionDigits: 2
        }) + ')');
    }

    // Validation: Ensure amount is positive
    const amount = parseFloat(current.getValue('amount') || 0);
    if (amount <= 0) {
        gs.addErrorMessage('Amount must be greater than zero');
        current.setAbortAction(true);
    }
}
